            array.add(Double.parseDouble(tmp[tmp.length - 1]));
        }

        ARL arl = new ARL(13);
        arl.loop(array.subList(200000,260000), false, 1000);
        arl.loop(array.subList(260000,270000), true, 1000);

        System.out.println(arl.toString());
    }
}

